/* ==========================================================================
   Caliber 08 — Aubry & Vent

   Colour is sampled from the reference movement photography on this page:
   the near-black of a macro ground, straight-grained German silver, the gilt
   of a train wheel, the ruby of a jewel, and the blue of a heated screw.
   ========================================================================== */

:root {
  /* ground */
  --ink: #0b0a09;
  --ink-2: #131210;
  --ink-3: #1c1a17;
  --hair-d: #302c26;
  --hair-d-2: #23201c;

  /* paper — the tone of a frosted German silver plate */
  --paper: #ece7dc;
  --paper-2: #e2dccd;
  --paper-3: #d6cfbd;
  --hair-l: #c6bfad;

  /* metal */
  --steel: #8c8578;
  --steel-hi: #c6bfaf;
  --gilt: #c1993f;
  --gilt-hi: #e2c27a;
  --gilt-ink: #7c5d19;
  --ruby: #a8495d;
  --blued: #5980b3;

  /* text */
  --on-ink: #d9d3c5;
  --on-ink-hi: #f4f0e6;
  --on-ink-dim: #8d8779;
  --on-paper: #17150f;
  --on-paper-dim: #5f594c;

  /* type */
  --serif: 'Zodiak', 'Iowan Old Style', Georgia, 'Times New Roman', serif;
  --sans: 'Synonym', ui-sans-serif, system-ui, 'Segoe UI', Helvetica, Arial, sans-serif;
  --mono: 'Martian Mono', ui-monospace, 'SFMono-Regular', 'Cascadia Mono', Menlo, monospace;

  /* motion — one grammar for the whole route */
  --t: 160ms;
  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
  --t-slow: 420ms;

  --wrap: 1240px;
  --gut: clamp(1.25rem, 4vw, 3.5rem);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 5.5rem;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ink);
  color: var(--on-ink);
  font-family: var(--sans);
  font-size: 1.0625rem;
  line-height: 1.65;
  font-synthesis-weight: none;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 400;
  letter-spacing: -0.015em;
  line-height: 1.02;
}

p {
  margin: 0;
  text-wrap: pretty;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

::selection {
  background: var(--gilt);
  color: var(--ink);
}

:focus-visible {
  outline: 2px solid var(--blued);
  outline-offset: 3px;
  border-radius: 1px;
}

.wrap {
  max-width: var(--wrap);
  margin-inline: auto;
  padding-inline: var(--gut);
}

.skip {
  position: fixed;
  top: 0.5rem;
  left: 0.5rem;
  z-index: 100;
  transform: translateY(-160%);
  background: var(--gilt);
  color: var(--ink);
  padding: 0.6rem 1rem;
  font-family: var(--mono);
  font-size: 0.75rem;
  text-decoration: none;
  transition: transform var(--t) var(--ease);
}
.skip:focus {
  transform: translateY(0);
}

.muted {
  color: var(--on-ink-dim);
}

/* --------------------------------- type ---------------------------------- */

.eyebrow {
  font-family: var(--mono);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gilt);
  margin: 0;
}

.sec--paper .eyebrow {
  color: var(--gilt-ink);
}

/* -------------------------------- buttons -------------------------------- */

.btn {
  --btn-fg: var(--on-ink-hi);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 44px;
  padding: 0.6rem 1.25rem;
  border: 1px solid var(--hair-d);
  border-radius: 2px;
  background: transparent;
  color: var(--btn-fg);
  font-family: var(--mono);
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.07em;
  text-decoration: none;
  cursor: pointer;
  transition: background var(--t) var(--ease), color var(--t) var(--ease),
    border-color var(--t) var(--ease), transform var(--t) var(--ease);
}

.btn--lg {
  min-height: 52px;
  padding: 0.85rem 1.6rem;
  font-size: 0.8125rem;
}

.btn--block {
  width: 100%;
}

.btn--gilt {
  background: var(--gilt);
  border-color: var(--gilt);
  color: #1a1408;
}
.btn--gilt:hover {
  background: var(--gilt-hi);
  border-color: var(--gilt-hi);
}
.btn--gilt:active {
  transform: translateY(1px);
  background: var(--gilt);
}

.btn--ghost:hover {
  border-color: var(--gilt);
  color: var(--gilt-hi);
  background: rgba(193, 153, 63, 0.07);
}
.btn--ghost:active {
  transform: translateY(1px);
}

.sec--paper .btn--ghost {
  --btn-fg: var(--on-paper);
  border-color: var(--hair-l);
}
.sec--paper .btn--ghost:hover {
  border-color: var(--gilt-ink);
  color: var(--gilt-ink);
  background: rgba(124, 93, 25, 0.06);
}

/* --------------------------------- beat ----------------------------------
   2.5 Hz. Five semi-oscillations a second, so one full swing is 400ms.
   This is the only automatic loop on the page and it is the product's
   defining fact, stated at its real rate.                                  */

.beat {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  flex: none;
}
.beat svg {
  display: block;
  overflow: visible;
}
.beat--sm svg {
  width: 20px;
  height: 20px;
}
.beat--md svg {
  width: 34px;
  height: 34px;
}
.beat--lg svg {
  width: 128px;
  height: 128px;
}
.beat__rim {
  fill: none;
  stroke: var(--hair-d);
  stroke-width: 1;
}
.beat--lg .beat__rim {
  stroke: var(--hair-d);
  stroke-dasharray: 2 6;
}
.beat__felloe {
  fill: none;
  stroke: var(--steel);
  stroke-width: 2.4;
}
.beat__arm {
  stroke: var(--steel);
  stroke-width: 1.6;
}
.beat__weight {
  fill: var(--steel-hi);
}
.beat__jewel {
  fill: var(--ruby);
}
.beat__wheel {
  transform-origin: 24px 24px;
}
.beat[data-running='true'] .beat__wheel {
  animation: swing 0.4s cubic-bezier(0.42, 0, 0.58, 1) infinite alternate;
}
@keyframes swing {
  from {
    transform: rotate(-33deg);
  }
  to {
    transform: rotate(33deg);
  }
}

/* -------------------------------- masthead -------------------------------- */

.masthead {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 10, 9, 0.72);
  backdrop-filter: blur(14px) saturate(140%);
  border-bottom: 1px solid transparent;
  transition: border-color var(--t-slow) var(--ease), background var(--t-slow) var(--ease);
}
.masthead[data-lifted='true'] {
  background: rgba(11, 10, 9, 0.94);
  border-bottom-color: var(--hair-d-2);
}
.masthead__in {
  max-width: var(--wrap);
  margin-inline: auto;
  padding: 0.7rem var(--gut);
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.brand {
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: var(--on-ink-hi);
  line-height: 1.15;
  flex: none;
}
.brand__house {
  font-family: var(--serif);
  font-size: 1.0625rem;
  letter-spacing: 0.01em;
}
.brand__cal {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--gilt);
}
.brand:hover .brand__cal {
  color: var(--gilt-hi);
}

.masthead__nav {
  display: flex;
  gap: 1.4rem;
  margin-inline: auto;
}
.masthead__nav a {
  position: relative;
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--on-ink-dim);
  text-decoration: none;
  padding-block: 0.4rem;
  transition: color var(--t) var(--ease);
}
.masthead__nav a::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  height: 1px;
  width: 100%;
  background: var(--gilt);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--t) var(--ease);
}
.masthead__nav a:hover {
  color: var(--on-ink-hi);
}
.masthead__nav a:hover::after {
  transform: scaleX(1);
}

.masthead__end {
  display: flex;
  align-items: center;
  gap: 1rem;
  flex: none;
}
.rate {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding-right: 1rem;
  border-right: 1px solid var(--hair-d-2);
}
.rate__num {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  color: var(--on-ink-dim);
}

/* --------------------------------- hero ---------------------------------- */

.hero {
  position: relative;
  border-bottom: 1px solid var(--hair-d-2);
  background:
    radial-gradient(120% 90% at 78% 22%, rgba(193, 153, 63, 0.08), transparent 62%),
    var(--ink);
}
.hero__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.82fr);
  gap: clamp(2rem, 5vw, 5rem);
  align-items: center;
  padding-block: clamp(3.5rem, 8vw, 7rem) clamp(3.5rem, 7vw, 6rem);
}

.hero__title {
  font-size: clamp(3.4rem, 8.4vw, 7.4rem);
  line-height: 0.92;
  margin: 1.1rem 0 0;
  color: var(--on-ink-hi);
  display: flex;
  align-items: baseline;
  gap: 0.22em;
  flex-wrap: wrap;
}
.hero__num {
  font-family: var(--mono);
  font-size: 0.46em;
  font-weight: 400;
  letter-spacing: -0.01em;
  color: var(--gilt);
  border-left: 1px solid var(--hair-d);
  padding-left: 0.36em;
}
.hero__sub {
  margin-top: 1.4rem;
  max-width: 30ch;
  font-size: clamp(1.15rem, 1.7vw, 1.4rem);
  line-height: 1.42;
  color: var(--on-ink-hi);
  font-family: var(--serif);
}
.hero__lead {
  margin-top: 1rem;
  max-width: 46ch;
  color: var(--on-ink-dim);
  font-size: 1rem;
  line-height: 1.7;
}
.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 2rem;
}
.hero__figures {
  display: flex;
  gap: clamp(1.5rem, 3vw, 3rem);
  margin: 2.6rem 0 0;
  padding-top: 1.5rem;
  border-top: 1px solid var(--hair-d-2);
}
.hero__figures dt {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-ink-dim);
}
.hero__figures dd {
  margin: 0.3rem 0 0;
  font-family: var(--serif);
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  color: var(--on-ink-hi);
  line-height: 1;
}

.hero__plate {
  margin: 0;
  position: relative;
}
.hero__plate img {
  width: 100%;
  filter: contrast(1.04) saturate(0.92);
}
.hero__plate::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(190deg, transparent 55%, rgba(11, 10, 9, 0.62));
  box-shadow: inset 0 0 0 1px var(--hair-d-2);
}
.hero__plate figcaption {
  margin-top: 0.75rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  line-height: 1.6;
  letter-spacing: 0.04em;
  color: var(--on-ink-dim);
}

/* ------------------------------- sections -------------------------------- */

.sec {
  padding-block: clamp(4.5rem, 9vw, 8.5rem);
}
.sec--dark {
  background: var(--ink);
  color: var(--on-ink);
}
.sec--paper {
  background: var(--paper);
  color: var(--on-paper);
}
.sec--paper + .sec--paper {
  padding-top: 0;
}

.sec__head {
  max-width: 44rem;
}
.sec__title {
  margin-top: 0.9rem;
  font-size: clamp(2.1rem, 4.2vw, 3.4rem);
}
.sec--dark .sec__title {
  color: var(--on-ink-hi);
}
.sec__intro {
  margin-top: 1.1rem;
  max-width: 54ch;
  color: var(--on-ink-dim);
}
.sec--paper .sec__intro {
  color: var(--on-paper-dim);
}
.rule {
  display: block;
  height: 1px;
  margin-top: 2rem;
  background: var(--hair-d);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 900ms var(--ease) 120ms;
}
.sec--paper .rule {
  background: var(--hair-l);
}
[data-revealed='true'] .rule,
.rule[data-revealed='true'] {
  transform: scaleX(1);
}

/* the one regional entrance, used everywhere, in one grammar */
.reveal {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity var(--t-slow) var(--ease), transform var(--t-slow) var(--ease);
}
.reveal[data-revealed='true'] {
  opacity: 1;
  transform: none;
}

/* ----------------------------- transmission ------------------------------ */

.transmission__body {
  margin-top: clamp(2.5rem, 5vw, 4rem);
  display: grid;
  grid-template-columns: 15rem minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 5rem);
  align-items: start;
}

.track {
  position: sticky;
  top: 7rem;
  display: grid;
  grid-template-columns: 3px 1fr;
  gap: 1.1rem;
  align-self: start;
}
.track__line {
  position: relative;
  width: 3px;
  background: var(--hair-d-2);
  align-self: stretch;
}
.track__fill {
  position: absolute;
  inset: 0 0 auto 0;
  display: block;
  background: linear-gradient(180deg, var(--gilt-hi), var(--gilt));
  box-shadow: 0 0 12px rgba(193, 153, 63, 0.5);
  transition: height 620ms var(--ease);
}
.track__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1.15rem;
}
.track__list li {
  display: grid;
  grid-template-columns: 2.1rem 1fr;
  align-items: baseline;
  gap: 0.5rem;
  transition: color var(--t) var(--ease), opacity var(--t) var(--ease);
  color: var(--on-ink-dim);
  opacity: 0.55;
}
.track__list li[data-state='past'] {
  opacity: 0.8;
  color: var(--steel);
}
.track__list li[data-state='on'] {
  opacity: 1;
  color: var(--on-ink-hi);
}
.track__roman {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.14em;
  color: var(--gilt);
}
.track__list li[data-state='off'] .track__roman {
  color: var(--on-ink-dim);
}
.track__name {
  font-family: var(--serif);
  font-size: 1.0625rem;
  line-height: 1.25;
}

/* mobile form of the same tracker */
.track__bar {
  display: none;
  position: sticky;
  top: 4.3rem;
  z-index: 20;
  padding: 0.55rem 0 0.5rem;
  background: rgba(11, 10, 9, 0.94);
  border-bottom: 1px solid var(--hair-d-2);
  margin-bottom: 1.5rem;
}
.track__bar-fill {
  display: block;
  height: 2px;
  background: var(--gilt);
  transition: width 620ms var(--ease);
}
.track__bar-label {
  display: block;
  margin-top: 0.45rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--on-ink-dim);
}

.stages {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: clamp(3.5rem, 7vw, 6.5rem);
}
.stage {
  display: grid;
  gap: 1rem;
  padding-top: 1.6rem;
  border-top: 1px solid var(--hair-d-2);
  transition: border-color var(--t-slow) var(--ease);
}
.stage[data-state='on'] {
  border-top-color: var(--gilt);
}
.stage__head {
  display: flex;
  align-items: baseline;
  gap: 1rem;
}
.stage__roman {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.16em;
  color: var(--gilt);
  flex: none;
  width: 2.4rem;
}
.stage__name {
  font-size: clamp(1.5rem, 2.6vw, 2.15rem);
  color: var(--on-ink-hi);
}
.stage__figure {
  font-family: var(--serif);
  font-size: clamp(1.6rem, 2.7vw, 2.4rem);
  line-height: 1.14;
  color: var(--gilt-hi);
  max-width: 20ch;
  margin-left: 3.4rem;
}
.stage__detail {
  max-width: 52ch;
  margin-left: 3.4rem;
  color: var(--on-ink-dim);
}
.stage__media {
  margin: 1.2rem 0 0 3.4rem;
  position: relative;
}
.stage__media img {
  width: 100%;
  box-shadow: inset 0 0 0 1px var(--hair-d-2);
  filter: saturate(0.94);
  transition: filter var(--t-slow) var(--ease);
}
.stage[data-state='off'] .stage__media img {
  filter: saturate(0.55) brightness(0.72);
}

.stage__mark {
  margin: 1.6rem 0 0 3.4rem;
  display: flex;
  align-items: center;
  gap: 1.75rem;
  padding: 1.75rem;
  border: 1px solid var(--hair-d-2);
  background: linear-gradient(160deg, var(--ink-2), var(--ink));
}
.stage__mark-note {
  font-family: var(--mono);
  font-size: 0.6875rem;
  line-height: 1.7;
  letter-spacing: 0.09em;
  color: var(--on-ink-dim);
  max-width: 18ch;
}
.stage__mark--balance {
  align-items: center;
}

.dia {
  width: 128px;
  height: 128px;
  flex: none;
  overflow: visible;
}
.dia__hair {
  fill: none;
  stroke: var(--hair-d);
  stroke-width: 1;
  stroke-dasharray: 2 6;
}
.dia__line {
  fill: none;
  stroke: var(--steel);
  stroke-width: 1.6;
}
.dia__thin {
  fill: none;
  stroke: var(--hair-d);
  stroke-width: 1.2;
}
.dia__fill {
  fill: var(--steel);
}
.dia__accent {
  fill: none;
  stroke: var(--gilt);
  stroke-width: 2.4;
  stroke-linecap: round;
}
.dia__tag {
  font-family: var(--mono);
  font-size: 11px;
  fill: var(--on-ink-dim);
  letter-spacing: 0.08em;
}

/* ----------------------------- construction ------------------------------ */

.construction__body {
  margin-top: clamp(2.5rem, 5vw, 4rem);
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4.5rem);
  align-items: start;
}

.elevation {
  display: grid;
  grid-template-columns: 6.5rem 1fr;
  gap: 0.75rem;
  padding: clamp(1.5rem, 3vw, 2.5rem);
  background: var(--paper-2);
  border: 1px solid var(--hair-l);
}
.elevation__dim {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.7rem;
  /* aligns to the stack, which is exactly 3.8mm at --px-per-mm */
  margin-block: 1.6rem;
}
.elevation__dim-line {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--gilt-ink);
}
.elevation__dim-line::before,
.elevation__dim-line::after {
  content: '';
  position: absolute;
  right: -4px;
  width: 9px;
  height: 1px;
  background: var(--gilt-ink);
}
.elevation__dim-line::before {
  top: 0;
}
.elevation__dim-line::after {
  bottom: 0;
}
.elevation__dim-label {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.1em;
  color: var(--gilt-ink);
  text-align: right;
  line-height: 1.4;
}

.stack {
  --px-per-mm: 62;
  display: flex;
  flex-direction: column;
  position: relative;
  padding-block: 1.6rem;
}
.stack__edge {
  position: absolute;
  left: 0;
  font-family: var(--mono);
  font-size: 0.5625rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-paper-dim);
}
.stack__edge--front {
  top: 0.2rem;
}
.stack__edge--back {
  bottom: 0.2rem;
}
.stack__layer {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: calc(var(--mm) * var(--px-per-mm) * 1px);
  min-height: 34px;
  padding-inline: 0.85rem;
  border: 1px solid var(--hair-l);
  border-bottom-width: 0;
  border-radius: 0;
  background-color: var(--paper-3);
  cursor: pointer;
  text-align: left;
  transition: transform 320ms var(--ease), box-shadow 320ms var(--ease),
    opacity var(--t) var(--ease), border-color var(--t) var(--ease);
}
.stack__layer:last-of-type {
  border-bottom-width: 1px;
}
.stack__layer:hover {
  transform: translateX(10px);
}
.stack__layer[data-on='true'] {
  transform: translateX(30px);
  border-color: var(--gilt-ink);
  box-shadow: -14px 0 22px -14px rgba(23, 21, 15, 0.55);
  z-index: 2;
}
.stack:hover .stack__layer[data-on='false'],
.stack:focus-within .stack__layer[data-on='false'] {
  opacity: 0.72;
}
.stack__label {
  font-family: var(--serif);
  font-size: 0.9375rem;
  color: var(--on-paper);
  line-height: 1.1;
}
.stack__mm {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  color: var(--on-paper-dim);
  flex: none;
}
.stack__layer[data-on='true'] .stack__mm {
  color: var(--gilt-ink);
}

/* surface treatments — diagram hatching, drawn from each layer's own note */
.stack__layer[data-surface='hairline'] {
  background-image: repeating-linear-gradient(
    0deg,
    rgba(23, 21, 15, 0.11) 0 1px,
    transparent 1px 4px
  );
}
.stack__layer[data-surface='frosted'] {
  background-image: radial-gradient(rgba(23, 21, 15, 0.16) 0.8px, transparent 0.9px);
  background-size: 7px 7px;
}
.stack__layer[data-surface='grained'] {
  background-image: repeating-linear-gradient(
    118deg,
    rgba(23, 21, 15, 0.13) 0 1px,
    transparent 1px 5px
  );
}
.stack__layer[data-surface='polished'] {
  background-image: linear-gradient(
    100deg,
    #46423a 0%,
    #8e8779 22%,
    #2c2924 46%,
    #b3ac9a 62%,
    #3a3730 100%
  );
}
.stack__layer[data-surface='polished'] .stack__label {
  color: var(--paper);
}
.stack__layer[data-surface='polished'] .stack__mm {
  color: var(--paper-3);
}
.stack__layer[data-surface='polished'][data-on='true'] .stack__mm {
  color: var(--gilt-hi);
}

.construction__read {
  display: grid;
  gap: 1.5rem;
}
.layercard {
  padding: clamp(1.5rem, 3vw, 2.25rem);
  border: 1px solid var(--hair-l);
  border-left: 3px solid var(--gilt-ink);
  background: var(--paper-2);
}
.layercard:focus {
  outline: none;
}
.layercard__idx {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--on-paper-dim);
}
.layercard__name {
  margin-top: 0.8rem;
  font-size: clamp(1.6rem, 2.6vw, 2.2rem);
}
.layercard__mm {
  margin-top: 0.35rem;
  font-family: var(--mono);
  font-size: 1.0625rem;
  color: var(--gilt-ink);
  letter-spacing: 0.02em;
}
.layercard__note {
  margin-top: 1rem;
  max-width: 46ch;
  color: var(--on-paper-dim);
}

.construction__plan {
  margin: 0;
}
.construction__plan img {
  width: 100%;
  box-shadow: 0 0 0 1px var(--hair-l);
}
.construction__plan figcaption {
  margin-top: 0.7rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  line-height: 1.65;
  color: var(--on-paper-dim);
  max-width: 46ch;
}

/* ----------------------------- specification ----------------------------- */

.spec {
  border-top: 1px solid var(--hair-l);
}
.spec__headline {
  margin-top: clamp(2rem, 4vw, 3rem);
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  background: var(--hair-l);
  border-block: 1px solid var(--hair-l);
}
.spec__headline > div {
  background: var(--paper);
  padding: 1.5rem 1.25rem;
  display: grid;
  gap: 0.4rem;
}
.spec__headline-v {
  font-family: var(--serif);
  font-size: clamp(1.7rem, 3vw, 2.6rem);
  line-height: 1;
}
.spec__headline-k {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-paper-dim);
}

.spec__list {
  margin: clamp(2rem, 4vw, 3rem) 0 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: clamp(2rem, 6vw, 5rem);
}
.spec__row {
  display: flex;
  align-items: baseline;
  gap: 0.75rem;
  padding-block: 0.85rem;
  border-bottom: 1px solid var(--hair-l);
}
.spec__row dt {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--on-paper-dim);
  flex: none;
}
.spec__row::after {
  content: '';
  flex: 1;
  border-bottom: 1px dotted var(--hair-l);
  transform: translateY(-0.2em);
  order: 1;
}
.spec__row dd {
  order: 2;
  margin: 0;
  font-family: var(--serif);
  font-size: 1.125rem;
  text-align: right;
  flex: none;
}

/* -------------------------------- workshop -------------------------------- */

.workshop__body {
  margin-top: clamp(2.5rem, 5vw, 4rem);
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4.5rem);
  align-items: start;
}
.workshop__figure {
  margin: 0;
  position: sticky;
  top: 7rem;
}
.workshop__figure img {
  width: 100%;
  box-shadow: inset 0 0 0 1px var(--hair-d-2);
  filter: saturate(0.72) contrast(1.05);
}
.workshop__figure figcaption {
  margin-top: 0.7rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  line-height: 1.65;
  color: var(--on-ink-dim);
}

.workshop__facts {
  display: grid;
  gap: 0;
}
.fact {
  display: grid;
  grid-template-columns: minmax(3.5rem, auto) minmax(0, 1fr);
  gap: 1.25rem;
  align-items: start;
  padding-block: 1.4rem;
  border-top: 1px solid var(--hair-d-2);
}
.fact p {
  color: var(--on-ink-dim);
  max-width: 42ch;
}
.fact__mark {
  font-family: var(--serif);
  font-size: clamp(2.6rem, 5.5vw, 4.4rem);
  line-height: 0.86;
  color: var(--gilt);
  letter-spacing: -0.02em;
}
.fact__mark--sm {
  font-size: clamp(1.4rem, 2.4vw, 1.9rem);
