}
.card:hover {
  border-color: var(--steel);
  box-shadow: 0 10px 30px -22px rgba(23, 21, 15, 0.6);
}
.card[data-on='true'] {
  border-color: var(--gilt-ink);
  background: var(--paper);
  box-shadow: inset 0 0 0 1px var(--gilt-ink);
}
.card__media {
  margin: 0;
  position: relative;
  overflow: hidden;
  background: var(--ink-2);
}
.card__media img {
  width: 100%;
  aspect-ratio: 760 / 950;
  object-fit: cover;
  filter: saturate(0.9);
  transition: transform 600ms var(--ease), filter var(--t-slow) var(--ease);
}
.card:hover .card__media img {
  transform: scale(1.028);
  filter: saturate(1);
}
.card__badge {
  position: absolute;
  top: 0;
  left: 0;
  background: var(--gilt);
  color: #1a1408;
  font-family: var(--mono);
  font-size: 0.5625rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  padding: 0.4rem 0.7rem;
}
.card__body {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  padding: clamp(1.1rem, 2vw, 1.6rem);
  flex: 1;
}
.card__name {
  font-size: 1.4rem;
}
.card__finish {
  color: var(--on-paper-dim);
  font-size: 0.9375rem;
  line-height: 1.55;
}
.card__price {
  margin-top: 0.4rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.18em;
  color: var(--on-paper-dim);
  display: flex;
  align-items: baseline;
  gap: 0.55rem;
}
.card__price span {
  font-family: var(--serif);
  font-size: 2rem;
  letter-spacing: -0.02em;
  color: var(--on-paper);
}
.card__lead {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  color: var(--on-paper);
}
.alloc {
  margin-top: 0.6rem;
  padding-top: 0.85rem;
  border-top: 1px solid var(--hair-l);
}
.alloc__ticks {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  max-width: 15rem;
}
.alloc__ticks i {
  display: block;
  width: 3px;
  height: 13px;
  background: var(--gilt-ink);
  opacity: 0.85;
}
.alloc__label {
  display: block;
  margin-top: 0.55rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.09em;
  color: var(--on-paper-dim);
}
.card__cta {
  margin-top: auto;
  width: 100%;
}

/* ------------------------------- reservation ------------------------------ */

.reserve__body {
  margin-top: clamp(2.5rem, 5vw, 4rem);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.9fr);
  gap: clamp(2rem, 5vw, 4.5rem);
  align-items: start;
}
.reserve__promise {
  font-family: var(--serif);
  font-size: clamp(1.3rem, 2.3vw, 1.85rem);
  line-height: 1.32;
  color: var(--on-ink-hi);
  max-width: 26ch;
}
.reserve__summary {
  margin: 2.25rem 0 0;
  border-top: 1px solid var(--hair-d-2);
}
.reserve__summary > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  padding-block: 0.85rem;
  border-bottom: 1px solid var(--hair-d-2);
}
.reserve__summary dt {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-ink-dim);
}
.reserve__summary dd {
  margin: 0;
  font-family: var(--serif);
  font-size: 1.0625rem;
  color: var(--on-ink-hi);
  text-align: right;
}

.reserve__panel {
  padding: clamp(1.5rem, 3vw, 2.5rem);
  background: var(--ink-2);
  border: 1px solid var(--hair-d);
}
.field {
  display: grid;
  gap: 0.5rem;
  margin-bottom: 1.35rem;
}
.field label {
  font-family: var(--mono);
  font-size: 0.625rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-ink-dim);
}
.field input,
.field select {
  min-height: 48px;
  padding: 0.6rem 0.85rem;
  background: var(--ink);
  border: 1px solid var(--hair-d);
  border-radius: 2px;
  color: var(--on-ink-hi);
  font-size: 1rem;
  transition: border-color var(--t) var(--ease), background var(--t) var(--ease);
}
.field select {
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, var(--steel) 50%),
    linear-gradient(135deg, var(--steel) 50%, transparent 50%);
