  outline: none;
}
.confirm__line {
  font-family: var(--serif);
  font-size: clamp(1.2rem, 2vw, 1.5rem);
  line-height: 1.38;
  color: var(--on-ink-hi);
}
.confirm__note {
  font-family: var(--mono);
  font-size: 0.6875rem;
  letter-spacing: 0.1em;
  color: var(--gilt);
