  display: block;
  font-size: 1.35rem;
  color: var(--on-ink-hi);
  margin-bottom: 0.9rem;
}
.foot__line {
  font-size: 0.875rem;
  color: var(--on-ink-dim);
  margin-bottom: 0.35rem;
}
