  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
  font-family: var(--serif);
  font-size: 1rem;
  color: var(--on-ink);
}
.foot__note {
  margin-top: 1rem;
  font-size: 0.8125rem;
  line-height: 1.65;
  color: var(--on-ink-dim);
  max-width: 52ch;
}
.foot__credits {
  list-style: none;
  margin: 1rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.4rem;
  font-family: var(--mono);
  font-size: 0.625rem;
  line-height: 1.7;
  color: var(--on-ink-dim);
}

/* ------------------------------- responsive ------------------------------- */

@media (max-width: 1080px) {
  .transmission__body {
    grid-template-columns: 11.5rem minmax(0, 1fr);
  }
  .construction__body,
  .workshop__body,
  .reserve__body {
    grid-template-columns: minmax(0, 1fr);
  }
  .workshop__figure {
    position: static;
  }
  .foot__in {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .foot__col--credits {
    grid-column: 1 / -1;
  }
}

@media (max-width: 900px) {
  .masthead__nav {
    display: none;
  }
  .masthead__in {
    justify-content: space-between;
  }
  .hero__grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .hero__plate {
    order: -1;
  }
  .cards {
    grid-template-columns: minmax(0, 1fr);
  }
  .card {
    display: grid;
    grid-template-columns: 11rem minmax(0, 1fr);
  }
  .card__media img {
    height: 100%;
    aspect-ratio: auto;
  }
}

@media (max-width: 720px) {
  html {
    scroll-padding-top: 8.5rem;
  }
  .track {
    display: none;
  }
  .track__bar {
    display: block;
  }
  .transmission__body {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }
  .stage__figure,
  .stage__detail,
  .stage__media,
  .stage__mark {
    margin-left: 0;
  }
  .stage__mark {
    flex-direction: column;
    align-items: flex-start;
    gap: 1.1rem;
    padding: 1.35rem;
  }
  .stage__mark-note {
    max-width: none;
  }
  .beat--lg svg {
    width: 88px;
    height: 88px;
  }
  .dia {
    width: 96px;
    height: 96px;
  }

  .hero__figures {
    gap: 1.5rem;
  }
  .hero__actions .btn {
    flex: 1 1 100%;
  }

  .elevation {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
    padding: 1.1rem;
  }
  /* on a phone the dimension bracket goes above the stack, not beside it */
  .elevation__dim {
    justify-content: flex-start;
    margin: 0 0 0.75rem;
    padding: 0;
  }
  .elevation__dim-line {
    display: none;
  }
  .stack {
    --px-per-mm: 54;
  }
  .stack__edge {
    font-size: 0.5rem;
  }

  .spec__headline {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .spec__list {
    grid-template-columns: minmax(0, 1fr);
  }

  .card {
    grid-template-columns: minmax(0, 1fr);
  }
  .card__media img {
    aspect-ratio: 16 / 11;
    object-position: center 45%;
  }
  .alloc__ticks {
    max-width: none;
  }

  .fact {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.5rem;
  }
  .fact--lead {
    gap: 0.6rem;
  }

  .foot__in {
    grid-template-columns: minmax(0, 1fr);
  }
}

@media (max-width: 420px) {
  .hero__title {
    font-size: 3rem;
  }
  .stack {
    --px-per-mm: 48;
  }
  .rate {
    display: none;
  }
}

/* ----------------------------- reduced motion ----------------------------- */

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  .beat[data-running='true'] .beat__wheel {
    /* held at the extreme of its swing rather than switched off, so the
       balance still reads as a balance */
    animation: none;
    transform: rotate(24deg);
  }
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  .rule {
    transform: scaleX(1);
    transition: none;
  }
  .track__fill,
  .track__bar-fill {
    transition: none;
  }
  .stack__layer,
  .card__media img,
  .btn {
    transition: none;
  }
  .stack__layer:hover {
    transform: none;
  }
  .card:hover .card__media img {
    transform: none;
  }
}

