import { chromium } from 'playwright'
const b = await chromium.launch()
const w = Number(process.argv[2] || 1440), h = Number(process.argv[3] || 900), tag = process.argv[4] || 'vp'
const p = await b.newPage({ viewport: { width: w, height: h } })
await p.goto('http://localhost:4174/', { waitUntil: 'networkidle' })
await p.evaluate(() => { document.documentElement.style.scrollBehavior = 'auto' })
const spots = process.argv.slice(5)
for (const s of spots) {
  const [name, sel, off] = s.split(':')
  await p.evaluate(([sel, off]) => {
    const el = document.querySelector(sel)
    window.scrollTo(0, el.getBoundingClientRect().top + window.scrollY + Number(off))
  }, [sel, off || 0])
  await p.waitForTimeout(900)
  await p.screenshot({ path: `.shots/${tag}-${name}.png` })
}
await b.close()
console.log('ok')
